import { test, expect } from '@playwright/test';

test.describe('Select All Rows with Header Checkbox', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should select all rows when header checkbox is clicked', async ({ page }) => {
    // Verify table header checkbox is visible
    const headerCheckbox = page.getByRole('checkbox', { name: /select all/i });
    await expect(headerCheckbox).toBeVisible();

    // Verify all rows are initially unchecked
    const rowCheckboxes = page.locator('[data-testid="row-checkbox"]');
    const rowCount = await rowCheckboxes.count();
    expect(rowCount).toBeGreaterThan(0);
    for (let i = 0; i < rowCount; i++) {
      const rowCheckbox = rowCheckboxes.nth(i);
      await expect(rowCheckbox).not.toBeChecked();
    }

    // Click the header checkbox to select all rows
    await headerCheckbox.click();

    // Verify all rows are now checked
    for (let i = 0; i < rowCount; i++) {
      const rowCheckbox = rowCheckboxes.nth(i);
      await expect(rowCheckbox).toBeChecked();
    }

    // Verify table header checkbox is checked
    await expect(headerCheckbox).toBeChecked();

    // Verify table header text is updated
    const headerText = page.getByText(/select all/i);
    await expect(headerText).toBeVisible();
  });

  test('should unselect all rows when header checkbox is unchecked', async ({ page }) => {
    // Verify table header checkbox is visible
    const headerCheckbox = page.getByRole('checkbox', { name: /select all/i });
    await expect(headerCheckbox).toBeVisible();

    // Verify all rows are initially checked
    const rowCheckboxes = page.locator('[data-testid="row-checkbox"]');
    const rowCount = await rowCheckboxes.count();
    for (let i = 0; i < rowCount; i++) {
      const rowCheckbox = rowCheckboxes.nth(i);
      await expect(rowCheckbox).toBeChecked();
    }

    // Click the header checkbox to unselect all rows
    await headerCheckbox.click();

    // Verify all rows are now unchecked
    for (let i = 0; i < rowCount; i++) {
      const rowCheckbox = rowCheckboxes.nth(i);
      await expect(rowCheckbox).not.toBeChecked();
    }

    // Verify table header checkbox is unchecked
    await expect(headerCheckbox).not.toBeChecked();

    // Verify table header text is updated
    const headerText = page.getByText(/unselect all/i);
    await expect(headerText).toBeVisible();
  });
});
